#!/usr/bin/env bash
#
# Runs tools/bench/run.sh over every program generated by tools/bench/gen.py and
# prints one table, so the speedup can be read against matrix complexity.
#
# Usage: tools/bench/sweep.sh [--iters N] [--repeats R] [--opt LEVEL]

set -uo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd "$here/../.." && pwd)"

iters=20000000
repeats=3
opt=O1

while [[ $# -gt 0 ]]; do
  case "$1" in
    --iters) iters="$2"; shift 2 ;;
    --repeats) repeats="$2"; shift 2 ;;
    --opt) opt="$2"; shift 2 ;;
    *) echo "unknown option '$1'" >&2; exit 1 ;;
  esac
done

programs="$root/build/bench"
if ! ls "$programs"/*.mlir >/dev/null 2>&1; then
  echo "no generated programs; running tools/bench/gen.py" >&2
  python3 "$here/gen.py" --outdir "$programs" >/dev/null || exit 1
fi

printf '%-16s %-10s %6s %5s %7s %6s %7s %9s %8s\n' \
  program method tests cond blocks insns branch ms speedup
printf '%.0s-' {1..86}; echo

for src in "$programs"/*.mlir; do
  name="$(basename "$src" .mlir)"
  family="${name%%-*}"
  driver="$here/drivers/$family.mlir"
  [[ -f "$driver" ]] || { echo "$name: no driver for family '$family'" >&2; continue; }
  "$here/run.sh" "$src" --driver "$driver" --iters "$iters" --repeats "$repeats" --opt "$opt" \
    | awk -v p="$name" 'NR > 1 { printf "%-16s %s\n", p, $0 }'
done
